// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"slices"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	accountsCopy := make([]Account, len(accounts))
	copy(accountsCopy, accounts)
	slices.SortStableFunc(accountsCopy, func(a, b Account) int {
		if a.ID < b.ID {
			return -1
		}
		if a.ID > b.ID {
			return 1
		}
		return 0
	})

	state := &serverState{accounts: accountsCopy}
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", state.health)
	mux.HandleFunc("/accounts", state.list)
	mux.HandleFunc("/accounts/{id}", state.get)

	return &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}
}

type serverState struct {
	accounts []Account
}

func (s *serverState) health(w http.ResponseWriter, r *http.Request) {
	if !requireGet(w, r) {
		return
	}

	_, _ = w.Write([]byte("ok"))
}

func (s *serverState) list(w http.ResponseWriter, r *http.Request) {
	if !requireGet(w, r) {
		return
	}

	accounts := s.accounts
	if values, ok := r.URL.Query()["active"]; ok {
		if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
			http.Error(w, "invalid active parameter", http.StatusBadRequest)
			return
		}

		active := values[0] == "true"
		accounts = make([]Account, 0, len(s.accounts))
		for _, account := range s.accounts {
			if account.Active == active {
				accounts = append(accounts, account)
			}
		}
	}

	writeJSON(w, accounts)
}

func (s *serverState) get(w http.ResponseWriter, r *http.Request) {
	if !requireGet(w, r) {
		return
	}

	id := r.PathValue("id")
	for _, account := range s.accounts {
		if account.ID == id {
			writeJSON(w, account)
			return
		}
	}

	http.NotFound(w, r)
}

func requireGet(w http.ResponseWriter, r *http.Request) bool {
	if r.Method == http.MethodGet {
		return true
	}

	w.Header().Set("Allow", http.MethodGet)
	http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
	return false
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(value)
}

// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"sort"
	"strings"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	ordered := make([]Account, len(accounts))
	copy(ordered, accounts)
	sort.SliceStable(ordered, func(i, j int) bool {
		return ordered[i].ID < ordered[j].ID
	})

	byID := make(map[string]Account, len(ordered))
	for _, account := range ordered {
		if _, exists := byID[account.ID]; !exists {
			byID[account.ID] = account
		}
	}

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var account Account
		var isAccount bool
		switch {
		case r.URL.Path == "/healthz":
			if r.Method != http.MethodGet {
				methodNotAllowed(w)
				return
			}
			w.Header().Set("Content-Type", "text/plain; charset=utf-8")
			_, _ = w.Write([]byte("ok"))
			return
		case r.URL.Path == "/accounts":
			if r.Method != http.MethodGet {
				methodNotAllowed(w)
				return
			}
		case strings.HasPrefix(r.URL.Path, "/accounts/") &&
			!strings.Contains(r.URL.Path[len("/accounts/"):], "/"):
			id := r.URL.Path[len("/accounts/"):]
			if id == "" {
				http.NotFound(w, r)
				return
			}
			account, isAccount = byID[id]
			if r.Method != http.MethodGet {
				methodNotAllowed(w)
				return
			}
			if !isAccount {
				http.NotFound(w, r)
				return
			}
		default:
			http.NotFound(w, r)
			return
		}

		if isAccount {
			writeJSON(w, account)
			return
		}

		filtered, message := filterAccounts(ordered, r)
		if message != "" {
			http.Error(w, message, http.StatusBadRequest)
			return
		}
		writeJSON(w, filtered)
	})

	return &http.Server{
		Addr:                addr,
		Handler:             handler,
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         15 * time.Second,
		WriteTimeout:        30 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
		MaxHeaderValueCount: 100,
	}
}

func filterAccounts(accounts []Account, r *http.Request) ([]Account, string) {
	activeValues, present := r.URL.Query()["active"]
	if !present {
		return append(make([]Account, 0, len(accounts)), accounts...), ""
	}
	if len(activeValues) != 1 || (activeValues[0] != "true" && activeValues[0] != "false") {
		return nil, "invalid query parameter: active"
	}

	wantActive := activeValues[0] == "true"
	filtered := make([]Account, 0, len(accounts))
	for _, account := range accounts {
		if account.Active == wantActive {
			filtered = append(filtered, account)
		}
	}
	return filtered, ""
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(value)
}

func methodNotAllowed(w http.ResponseWriter) {
	w.Header().Set("Allow", http.MethodGet)
	http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
}

// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	accounts = slices.Clone(accounts)
	slices.SortStableFunc(accounts, func(a, b Account) int {
		return strings.Compare(a.ID, b.ID)
	})

	byID := make(map[string]Account, len(accounts))
	for _, account := range accounts {
		byID[account.ID] = account
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		switch {
		case r.URL.Path == "/healthz":
			if !getOnly(w, r) {
				return
			}
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write([]byte("ok"))
		case r.URL.Path == "/accounts":
			if !getOnly(w, r) {
				return
			}
			handleAccounts(w, r, accounts)
		case strings.HasPrefix(r.URL.Path, "/accounts/"):
			id := strings.TrimPrefix(r.URL.Path, "/accounts/")
			if id == "" || strings.Contains(id, "/") {
				http.NotFound(w, r)
				return
			}
			if !getOnly(w, r) {
				return
			}
			account, ok := byID[id]
			if !ok {
				http.NotFound(w, r)
				return
			}
			writeJSON(w, account)
		default:
			http.NotFound(w, r)
		}
	})

	return &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}
}

func getOnly(w http.ResponseWriter, r *http.Request) bool {
	if r.Method == http.MethodGet {
		return true
	}
	w.Header().Set("Allow", http.MethodGet)
	w.WriteHeader(http.StatusMethodNotAllowed)
	return false
}

func handleAccounts(w http.ResponseWriter, r *http.Request, accounts []Account) {
	values, present := r.URL.Query()["active"]
	if present {
		if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
			http.Error(w, "invalid query parameter: active\n", http.StatusBadRequest)
			return
		}
	}

	filtered := make([]Account, 0, len(accounts))
	for _, account := range accounts {
		if !present || (values[0] == "true") == account.Active {
			filtered = append(filtered, account)
		}
	}
	writeJSON(w, filtered)
}

func writeJSON(w http.ResponseWriter, value any) {
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(value)
}

// Package gateway serves the public read-only accounts API.
package gateway

import (
	"encoding/json"
	"net/http"
	"net/url"
	"slices"
	"sort"
	"strings"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	accounts = slices.Clone(accounts)
	sort.SliceStable(accounts, func(i, j int) bool {
		return accounts[i].ID < accounts[j].ID
	})

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := r.URL.Path
		isHealth := path == "/healthz"
		isList := path == "/accounts"
		isAccount := strings.HasPrefix(path, "/accounts/") &&
			!strings.Contains(path[len("/accounts/"):], "/") &&
			len(path) > len("/accounts/")

		if !isHealth && !isList && !isAccount {
			http.NotFound(w, r)
			return
		}
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
			return
		}

		if isHealth {
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write([]byte("ok"))
			return
		}

		if isList {
			query, err := url.ParseQuery(r.URL.RawQuery)
			if err != nil || len(query["active"]) > 1 {
				http.Error(w, `invalid query parameter "active"`, http.StatusBadRequest)
				return
			}

			filtered := make([]Account, 0, len(accounts))
			if values, ok := query["active"]; ok {
				if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
					http.Error(w, `invalid query parameter "active"`, http.StatusBadRequest)
					return
				}
				active := values[0] == "true"
				for _, account := range accounts {
					if account.Active == active {
						filtered = append(filtered, account)
					}
				}
			} else {
				filtered = append(filtered, accounts...)
			}

			writeJSON(w, filtered)
			return
		}

		id := path[len("/accounts/"):]
		for _, account := range accounts {
			if account.ID == id {
				writeJSON(w, account)
				return
			}
		}
		http.NotFound(w, r)
	})

	return &http.Server{
		Addr:                addr,
		Handler:             handler,
		ReadHeaderTimeout:   5 * time.Second,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		IdleTimeout:         60 * time.Second,
		MaxHeaderBytes:      1 << 20,
