func TestNewServerRoutes(t *testing.T) {
	server := NewServer(":8080", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
	})

	tests := []struct {
		name        string
		method      string
		target      string
		status      int
		contentType string
		body        string
	}{
		{name: "health", method: http.MethodGet, target: "/healthz", status: http.StatusOK, body: "ok"},
		{name: "health method", method: http.MethodPost, target: "/healthz", status: http.StatusMethodNotAllowed},
		{name: "accounts", method: http.MethodGet, target: "/accounts", status: http.StatusOK, contentType: "application/json", body: `[{"id":"a","name":"Alpha","cents":100,"active":true},{"id":"b","name":"Beta","cents":200,"active":false}]` + "\n"},
		{name: "active accounts", method: http.MethodGet, target: "/accounts?active=true", status: http.StatusOK, contentType: "application/json", body: `[{"id":"a","name":"Alpha","cents":100,"active":true}]` + "\n"},
		{name: "invalid active", method: http.MethodGet, target: "/accounts?active=1", status: http.StatusBadRequest, contentType: "text/plain; charset=utf-8", body: "invalid value for \"active\"\n"},
		{name: "account", method: http.MethodGet, target: "/accounts/a", status: http.StatusOK, contentType: "application/json", body: `{"id":"a","name":"Alpha","cents":100,"active":true}` + "\n"},
		{name: "missing account", method: http.MethodGet, target: "/accounts/missing", status: http.StatusNotFound, contentType: "text/plain; charset=utf-8", body: "404 page not found\n"},
		{name: "unknown path", method: http.MethodGet, target: "/missing", status: http.StatusNotFound, contentType: "text/plain; charset=utf-8", body: "404 page not found\n"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			recorder := httptest.NewRecorder()
			request := httptest.NewRequest(tt.method, tt.target, nil)

			server.Handler.ServeHTTP(recorder, request)

			if recorder.Code != tt.status {
				t.Errorf("NewServer().Handler.ServeHTTP(%s %s) status = %d, want %d", tt.method, tt.target, recorder.Code, tt.status)
			}
			if got := recorder.Header().Get("Content-Type"); got != tt.contentType {
				t.Errorf("NewServer().Handler.ServeHTTP(%s %s) Content-Type = %q, want %q", tt.method, tt.target, got, tt.contentType)
			}
			if got := recorder.Body.String(); got != tt.body {
				t.Errorf("NewServer().Handler.ServeHTTP(%s %s) body = %q, want %q", tt.method, tt.target, got, tt.body)
			}
		})
	}
}

