package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestServerRoutes(t *testing.T) {
	server := NewServer("", []Account{
		{ID: "b", Name: "Beta", Active: false},
		{ID: "a", Name: "Alpha", Active: true},
	})

	tests := []struct {
		name       string
		method     string
		target     string
		wantStatus int
		wantBody   string
	}{
		{name: "health", method: http.MethodGet, target: "/healthz", wantStatus: http.StatusOK, wantBody: "ok"},
		{
			name:       "accounts are sorted",
			method:     http.MethodGet,
			target:     "/accounts",
			wantStatus: http.StatusOK,
			wantBody:   `[{"id":"a","name":"Alpha","cents":0,"active":true},{"id":"b","name":"Beta","cents":0,"active":false}]` + "\n",
		},
		{
			name:       "active filter",
			method:     http.MethodGet,
			target:     "/accounts?active=true",
			wantStatus: http.StatusOK,
			wantBody:   `[{"id":"a","name":"Alpha","cents":0,"active":true}]` + "\n",
		},
		{
			name:       "invalid active filter",
			method:     http.MethodGet,
			target:     "/accounts?active=maybe",
			wantStatus: http.StatusBadRequest,
			wantBody:   "invalid query parameter: active\n\n",
		},
		{name: "wrong method", method: http.MethodPost, target: "/healthz", wantStatus: http.StatusMethodNotAllowed},
		{name: "unknown account", method: http.MethodGet, target: "/accounts/missing", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			recorder := httptest.NewRecorder()
			request := httptest.NewRequest(test.method, test.target, nil)
			server.Handler.ServeHTTP(recorder, request)

			if recorder.Code != test.wantStatus {
				t.Errorf("%s %s status = %d, want %d", test.method, test.target, recorder.Code, test.wantStatus)
			}
			if recorder.Body.String() != test.wantBody {
				t.Errorf("%s %s body = %q, want %q", test.method, test.target, recorder.Body.String(), test.wantBody)
			}
		})
	}
}

