package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestServerResponses(t *testing.T) {
	server := NewServer("", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
	})

	tests := []struct {
		name       string
		method     string
		path       string
		wantStatus int
		wantHeader string
		wantAllow  string
		wantBody   string
	}{
		{name: "health", method: http.MethodGet, path: "/healthz", wantStatus: http.StatusOK, wantBody: "ok"},
		{name: "accounts", method: http.MethodGet, path: "/accounts", wantStatus: http.StatusOK, wantHeader: "application/json", wantBody: `[{"id":"a","name":"Alpha","cents":100,"active":true},{"id":"b","name":"Beta","cents":200,"active":false}]` + "\n"},
		{name: "active accounts", method: http.MethodGet, path: "/accounts?active=true", wantStatus: http.StatusOK, wantHeader: "application/json", wantBody: `[{"id":"a","name":"Alpha","cents":100,"active":true}]` + "\n"},
		{name: "account", method: http.MethodGet, path: "/accounts/a", wantStatus: http.StatusOK, wantHeader: "application/json", wantBody: `{"id":"a","name":"Alpha","cents":100,"active":true}` + "\n"},
		{name: "unknown account", method: http.MethodGet, path: "/accounts/missing", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
		{name: "invalid filter", method: http.MethodGet, path: "/accounts?active=yes", wantStatus: http.StatusBadRequest, wantBody: "invalid query parameter: active\n\n"},
		{name: "method not allowed", method: http.MethodPost, path: "/accounts", wantStatus: http.StatusMethodNotAllowed, wantAllow: http.MethodGet},
		{name: "unknown path", method: http.MethodGet, path: "/other", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			req := httptest.NewRequest(test.method, test.path, nil)
			response := httptest.NewRecorder()
			server.Handler.ServeHTTP(response, req)

			if response.Code != test.wantStatus {
				t.Fatalf("status = %d, want %d", response.Code, test.wantStatus)
			}
			if got := response.Header().Get("Content-Type"); test.wantHeader != "" && got != test.wantHeader {
				t.Errorf("Content-Type = %q, want %q", got, test.wantHeader)
			}
			if got := response.Header().Get("Allow"); test.wantAllow != "" && got != test.wantAllow {
				t.Errorf("Allow = %q, want %q", got, test.wantAllow)
			}
			if response.Body.String() != test.wantBody {
				t.Errorf("body = %q, want %q", response.Body.String(), test.wantBody)
			}
		})
	}
}

