			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
			return
		}

		if path == "/healthz" {
			w.WriteHeader(http.StatusOK)
			_, _ = w.Write([]byte("ok"))
			return
		}

		if path == "/accounts" {
			serveAccountList(w, r.URL.RawQuery, accounts)
			return
		}

		serveAccount(w, r, path[len("/accounts/"):], accounts)
	})

	return &http.Server{
