		return
	}

	filtered := make([]Account, 0, len(accounts))
	if values, ok := query["active"]; ok {
		if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
			http.Error(w, `invalid query parameter "active"`, http.StatusBadRequest)
			return
		}
		active := values[0] == "true"
		for _, account := range accounts {
			if account.Active == active {
				filtered = append(filtered, account)
			}
		}
	} else {
		filtered = append(filtered, accounts...)
	}

	writeJSON(w, filtered)
}

func serveAccount(w http.ResponseWriter, r *http.Request, id string, accounts []Account) {
	for _, account := range accounts {
		if account.ID == id {
			writeJSON(w, account)
			return
		}
	}
	http.NotFound(w, r)
}

