		path := r.URL.Path
		isHealth := path == "/healthz"
		isList := path == "/accounts"
		accountID, hasAccountPrefix := strings.CutPrefix(path, "/accounts/")
		isAccount := hasAccountPrefix && accountID != "" && !strings.Contains(accountID, "/")

		if !isHealth && !isList && !isAccount {
			http.NotFound(w, r)
