	if accounts == nil {
		accounts = make([]Account, 0)
	}
	slices.SortStableFunc(accounts, func(a, b Account) int {
		return strings.Compare(a.ID, b.ID)
	})

	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
