	if r.Method != http.MethodGet {
		methodNotAllowed(w)
		return
	}

	id := strings.TrimPrefix(r.URL.Path, "/accounts/")
	if id == "" || strings.Contains(id, "/") {
		http.NotFound(w, r)
		return
	}
	for _, account := range accounts {
		if account.ID == id {
			writeJSON(w, http.StatusOK, account)
			return
		}
	}
	http.NotFound(w, r)
}

