package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestNewServer(t *testing.T) {
	server := NewServer("", []Account{
		{ID: "b", Name: "B", Cents: 2, Active: false},
		{ID: "a", Name: "A", Cents: 1, Active: true},
		{ID: "a", Name: "duplicate", Cents: 3, Active: false},
	})

	tests := []struct {
		name       string
		method     string
		target     string
		wantStatus int
		wantType   string
		wantAllow  string
		wantBody   string
	}{
		{
			name:       "health",
			method:     http.MethodGet,
			target:     "/healthz",
			wantStatus: http.StatusOK,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "ok",
		},
		{
			name:       "accounts are sorted and duplicate IDs keep the first account",
			method:     http.MethodGet,
			target:     "/accounts",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `[{"id":"a","name":"A","cents":1,"active":true},{"id":"a","name":"duplicate","cents":3,"active":false},{"id":"b","name":"B","cents":2,"active":false}]` + "\n",
		},
		{
			name:       "active filter",
			method:     http.MethodGet,
			target:     "/accounts?active=true",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `[{"id":"a","name":"A","cents":1,"active":true}]` + "\n",
		},
		{
			name:       "inactive filter",
			method:     http.MethodGet,
			target:     "/accounts?active=false",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `[{"id":"a","name":"duplicate","cents":3,"active":false},{"id":"b","name":"B","cents":2,"active":false}]` + "\n",
		},
		{
			name:       "invalid filter",
			method:     http.MethodGet,
			target:     "/accounts?active=maybe",
			wantStatus: http.StatusBadRequest,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "invalid query parameter: active\n",
		},
		{
			name:       "duplicate filter values",
			method:     http.MethodGet,
			target:     "/accounts?active=true&active=false",
			wantStatus: http.StatusBadRequest,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "invalid query parameter: active\n",
		},
		{
			name:       "known account",
			method:     http.MethodGet,
			target:     "/accounts/a",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `{"id":"a","name":"A","cents":1,"active":true}` + "\n",
		},
		{
			name:       "unknown account",
			method:     http.MethodGet,
			target:     "/accounts/missing",
			wantStatus: http.StatusNotFound,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "404 page not found\n",
		},
		{
			name:       "empty account ID",
			method:     http.MethodGet,
			target:     "/accounts/",
			wantStatus: http.StatusNotFound,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "404 page not found\n",
		},
		{
			name:       "nested account path",
			method:     http.MethodGet,
			target:     "/accounts/a/details",
			wantStatus: http.StatusNotFound,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "404 page not found\n",
		},
		{
			name:       "unknown path",
			method:     http.MethodGet,
			target:     "/other",
			wantStatus: http.StatusNotFound,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "404 page not found\n",
		},
		{
			name:       "method on known path",
			method:     http.MethodPost,
			target:     "/accounts",
			wantStatus: http.StatusMethodNotAllowed,
			wantType:   "text/plain; charset=utf-8",
			wantAllow:  http.MethodGet,
			wantBody:   "method not allowed\n",
		},
		{
			name:       "method on health",
			method:     http.MethodHead,
			target:     "/healthz",
			wantStatus: http.StatusMethodNotAllowed,
			wantType:   "text/plain; charset=utf-8",
			wantAllow:  http.MethodGet,
			wantBody:   "method not allowed\n",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			recorder := httptest.NewRecorder()
			request := httptest.NewRequest(test.method, test.target, nil)

			server.Handler.ServeHTTP(recorder, request)

			if recorder.Code != test.wantStatus {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) status = %d, want %d", "", test.method, test.target, recorder.Code, test.wantStatus)
			}
			if got := recorder.Header().Get("Content-Type"); got != test.wantType {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) Content-Type = %q, want %q", "", test.method, test.target, got, test.wantType)
			}
			if got := recorder.Header().Get("Allow"); got != test.wantAllow {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) Allow = %q, want %q", "", test.method, test.target, got, test.wantAllow)
			}
			if got := recorder.Body.String(); got != test.wantBody {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) body = %q, want %q", "", test.method, test.target, got, test.wantBody)
			}
		})
	}
}

