package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestServerRoutes(t *testing.T) {
	server := NewServer("", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
	})

	tests := []struct {
		name       string
		method     string
		path       string
		wantStatus int
		wantBody   string
	}{
		{name: "health", method: http.MethodGet, path: "/healthz", wantStatus: http.StatusOK, wantBody: "ok"},
		{name: "accounts", method: http.MethodGet, path: "/accounts", wantStatus: http.StatusOK, wantBody: "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true},{\"id\":\"b\",\"name\":\"Beta\",\"cents\":200,\"active\":false}]\n"},
		{name: "active accounts", method: http.MethodGet, path: "/accounts?active=true", wantStatus: http.StatusOK, wantBody: "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}]\n"},
		{name: "account", method: http.MethodGet, path: "/accounts/a", wantStatus: http.StatusOK, wantBody: "{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}\n"},
		{name: "invalid filter", method: http.MethodGet, path: "/accounts?active=maybe", wantStatus: http.StatusBadRequest, wantBody: "invalid value for \"active\"\n"},
		{name: "missing account", method: http.MethodGet, path: "/accounts/missing", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
		{name: "unknown path", method: http.MethodGet, path: "/unknown", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
		{name: "known path method", method: http.MethodPost, path: "/accounts", wantStatus: http.StatusMethodNotAllowed, wantBody: ""},
		{name: "unknown path method", method: http.MethodPost, path: "/unknown", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			recording := httptest.NewRecorder()
			request := httptest.NewRequest(test.method, test.path, nil)

			server.Handler.ServeHTTP(recording, request)

			if recording.Code != test.wantStatus {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s, %q) status = %d, want %d", "", test.method, test.path, recording.Code, test.wantStatus)
			}
			if recording.Body.String() != test.wantBody {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s, %q) body = %q, want %q", "", test.method, test.path, recording.Body.String(), test.wantBody)
			}
		})
	}
}

