		{name: "invalid active", method: http.MethodGet, target: "/accounts?active=maybe", status: http.StatusBadRequest, body: "invalid query parameter \"active\"\n", contentType: "text/plain; charset=utf-8"},
		{name: "duplicate active", method: http.MethodGet, target: "/accounts?active=true&active=false", status: http.StatusBadRequest, body: "invalid query parameter \"active\"\n", contentType: "text/plain; charset=utf-8"},
		{name: "unknown path", method: http.MethodGet, target: "/other", status: http.StatusNotFound, body: "404 page not found\n", contentType: "text/plain; charset=utf-8"},
		{name: "known path method", method: http.MethodPost, target: "/accounts", status: http.StatusMethodNotAllowed, body: "Method Not Allowed\n", contentType: "text/plain; charset=utf-8", allow: http.MethodGet},
		{name: "unknown path method", method: http.MethodPost, target: "/other", status: http.StatusNotFound, body: "404 page not found\n", contentType: "text/plain; charset=utf-8"},
	}

	for _, test := range tests {
