			}
			if response.Body.String() != test.body {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) body = %q, want %q", server.Addr, test.method, test.target, response.Body.String(), test.body)
			}
			if got := response.Header().Get("Content-Type"); got != test.contentType {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) Content-Type = %q, want %q", server.Addr, test.method, test.target, got, test.contentType)
			}
			if got := response.Header().Get("Allow"); got != test.allow {
				t.Errorf("NewServer(%q).Handler.ServeHTTP(%s %s) Allow = %q, want %q", server.Addr, test.method, test.target, got, test.allow)
			}
		})
	}
}

func TestNewServerSettings(t *testing.T) {
	server := NewServer("127.0.0.1:8080", nil)

	if server.ReadHeaderTimeout != 5*time.Second || server.ReadTimeout != 10*time.Second || server.WriteTimeout != 10*time.Second || server.IdleTimeout != 60*time.Second {
		t.Errorf("NewServer(%q) timeouts = (%s, %s, %s, %s), want (5s, 10s, 10s, 1m)", server.Addr, server.ReadHeaderTimeout, server.ReadTimeout, server.WriteTimeout, server.IdleTimeout)
	}
	if server.MaxHeaderBytes != 1<<20 || server.MaxHeaderValueCount != 100 {
		t.Errorf("NewServer(%q) limits = (%d, %d), want (1048576, 100)", server.Addr, server.MaxHeaderBytes, server.MaxHeaderValueCount)
	}
}

