		{name: "accounts", method: http.MethodGet, path: "/accounts", wantStatus: http.StatusOK, wantBody: `[{"id":"a","name":"A","cents":1,"active":true},{"id":"b","name":"B","cents":2,"active":false}]
`},
		{name: "active filter", method: http.MethodGet, path: "/accounts?active=true", wantStatus: http.StatusOK, wantBody: `[{"id":"a","name":"A","cents":1,"active":true}]
`},
		{name: "account", method: http.MethodGet, path: "/accounts/a", wantStatus: http.StatusOK, wantBody: `{"id":"a","name":"A","cents":1,"active":true}
`},
		{name: "unknown account", method: http.MethodGet, path: "/accounts/missing", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
		{name: "invalid filter", method: http.MethodGet, path: "/accounts?active=maybe", wantStatus: http.StatusBadRequest, wantBody: "invalid value for \"active\"\n"},
		{name: "unknown path", method: http.MethodGet, path: "/other", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
		{name: "known path wrong method", method: http.MethodPost, path: "/accounts", wantStatus: http.StatusMethodNotAllowed},
		{name: "unknown path wrong method", method: http.MethodPost, path: "/other", wantStatus: http.StatusNotFound, wantBody: "404 page not found\n"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			request := httptest.NewRequest(test.method, test.path, nil)
			recorder := httptest.NewRecorder()
			server.Handler.ServeHTTP(recorder, request)

			if recorder.Code != test.wantStatus {
				t.Errorf("NewServer(%q).ServeHTTP(%s %s) status = %d, want %d", "", test.method, test.path, recorder.Code, test.wantStatus)
			}
			if recorder.Body.String() != test.wantBody {
				t.Errorf("NewServer(%q).ServeHTTP(%s %s) body = %q, want %q", "", test.method, test.path, recorder.Body.String(), test.wantBody)
			}
		})
	}
}

func TestNewServerNilAccountsRendersArray(t *testing.T) {
	server := NewServer("", nil)
	request := httptest.NewRequest(http.MethodGet, "/accounts", nil)
	recorder := httptest.NewRecorder()
	server.Handler.ServeHTTP(recorder, request)

	if recorder.Body.String() != "[]\n" {
		t.Errorf("NewServer(%q).ServeHTTP(GET /accounts) body = %q, want %q", "", recorder.Body.String(), "[]\n")
	}
}

