	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

func serveAccount(w http.ResponseWriter, r *http.Request, accounts []Account) {
	id := strings.TrimPrefix(r.URL.Path, "/accounts/")
	if id == "" || strings.Contains(id, "/") {
		http.NotFound(w, r)
		return
	}
	for _, account := range accounts {
		if account.ID == id {
			writeJSON(w, http.StatusOK, account)
			return
		}
	}
	http.NotFound(w, r)
}

func methodNotAllowed(w http.ResponseWriter) {
	w.WriteHeader(http.StatusMethodNotAllowed)
}

func writeAccounts(w http.ResponseWriter, r *http.Request, accounts []Account) {
	filtered := accounts
	if values, ok := r.URL.Query()["active"]; ok {
		if len(values) != 1 || (values[0] != "true" && values[0] != "false") {
			http.Error(w, `invalid value for "active"`, http.StatusBadRequest)
			return
		}

		active := values[0] == "true"
		filtered = make([]Account, 0, len(accounts))
		for _, account := range accounts {
			if account.Active == active {
				filtered = append(filtered, account)
			}
		}
	}

	writeJSON(w, http.StatusOK, filtered)
}

